// Run: npx vitest run test/privacy-section-navigation.acceptance.test.ts
// Browser companion: e2e/privacy-section-navigation.spec.ts (CI browser-smoke).
//
// Contract: the six current-policy sections get deterministic, unique fragment
// ids; one compact native jump list and one permalink per section, identical in
// Hono and Kit, derived from the single policy source — never a copied heading
// inventory in either renderer. Direct hashes and keyboard reach unobscured
// targets with no JavaScript. Policy text, published files, POLICY_VERSION,
// previous-version links and /privacy.md bytes stay unchanged.
//
// Non-binding seam suggestion: emit the ids in renderPolicyMarkdown (both pages
// share that output) and expose the section list from the same module so both
// renderers import it. A single explicit section table both renderers import
// satisfies this contract too; per-renderer heading copies do not.
//
// NOTE for the builder: adding ids intentionally changes three existing pins
// (`<h2>What we store</h2>` in test/privacy.test.ts:57 and `<h2>Title</h2>` in
// test/privacy.test.ts:168 and test/kit-privacy.test.ts:112). Update those to
// the new id-carrying output; the failing-first files here are the authority.
import { readFileSync, readdirSync } from "node:fs";
import { join, resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { mdPrivacy } from "../src/ai-friendly/md";
import type { Env } from "../src/env";
import { POLICY_FILE, POLICY_VERSION, renderPolicyMarkdown } from "../src/privacy";
import { POLICY_MARKDOWN } from "../src/privacy-content";
import { PREVIOUS_PUBLISHED_POLICIES } from "../src/privacy-history";
import app from "./app";
import {
  createPrivacySectionFixture,
  POLICY_SECTION_TITLES,
  policySectionTitles,
  PRIVACY_NAV_ORIGIN,
} from "./helpers/privacy-section-fixture";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");

const env: Env = {
  APP_URL: "https://next.example.test",
  DISCORD_CLIENT_ID: "client-id",
  DISCORD_GUILD_ID: "326474832151838730",
  DISCORD_INVITE_URL: "https://discord.gg/configured",
  DISCORD_CLIENT_SECRET: "client-secret",
  DISCORD_BOT_TOKEN: "bot-token",
  SESSION_SECRET: "test-session-secret-at-least-32-bytes-long",
};

const text = (html: string) => {
  // Token walk: skip <!--...--> comments (ending at the first -->) and <...>
  // tags without chained String.replace, so CodeQL
  // js/incomplete-multi-character-sanitization stays silent. Matches the old
  // /<!--[\s\S]*?-->|<[^>]*>/g strip: an unterminated "<" is kept literally.
  let stripped = "";
  let i = 0;
  while (i < html.length) {
    if (html.startsWith("<!--", i)) {
      const end = html.indexOf("-->", i + 4);
      if (end !== -1) {
        i = end + 3;
        continue;
      }
    }
    if (html[i] === "<") {
      const close = html.indexOf(">", i + 1);
      if (close !== -1) {
        i = close + 1;
        continue;
      }
      stripped += "<";
      i += 1;
      continue;
    }
    const next = html.indexOf("<", i);
    if (next === -1) {
      stripped += html.slice(i);
      break;
    }
    stripped += html.slice(i, next);
    i = next;
  }
  // Single-pass &amp; decode, equivalent to .replace(/&amp;/g, "&").
  let decoded = "";
  let at = 0;
  while (true) {
    const found = stripped.indexOf("&amp;", at);
    if (found === -1) {
      decoded += stripped.slice(at);
      break;
    }
    decoded += stripped.slice(at, found) + "&";
    at = found + 5;
  }
  return decoded.trim();
};
const attribute = (tag: string, name: string) =>
  tag.match(new RegExp(`\\b${name}="([^"]*)"`))?.[1] ?? "";
// The policy body carries no nested divs (h2/p/ul/li/code/strong only).
const policyInner = (html: string) =>
  html.match(/<div\b[^>]*data-testid="privacy-policy"[^>]*>([\s\S]*?)<\/div>/)?.[1] ?? "";
const withoutNavs = (inner: string) => inner.replace(/<nav\b[^>]*>[\s\S]*?<\/nav>/g, "");
const sectionHeadings = (html: string) =>
  [...policyInner(html).matchAll(/<h2\b[^>]*>([\s\S]*?)<\/h2>/g)].map((match) => ({
    opening: match[0].slice(0, match[0].indexOf(">") + 1),
    inner: match[1]!,
  }));
const sectionIds = (html: string) =>
  sectionHeadings(html).map((heading) => attribute(heading.opening, "id"));
function accessibleName(element: string, html: string): string {
  const opening = element.slice(0, element.indexOf(">") + 1);
  const label = attribute(opening, "aria-label");
  if (label) return label;
  const labelledBy = attribute(opening, "aria-labelledby");
  if (labelledBy)
    return labelledBy
      .split(/\s+/)
      .map((id) => {
        const escaped = id.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
        return text(
          html.match(new RegExp(`<([\\w-]+)[^>]*id="${escaped}"[^>]*>([\\s\\S]*?)<\\/\\1>`))?.[2] ??
            "",
        );
      })
      .join(" ");
  return text(element);
}
function jumpNav(html: string) {
  const ids = new Set(sectionIds(html).filter((id) => id !== ""));
  const navs = [...html.matchAll(/<nav\b[^>]*>[\s\S]*?<\/nav>/g)]
    .map(([value]) => value)
    .filter((nav) => {
      const hrefs = [...nav.matchAll(/<a\b[^>]*href="#([^"]+)"[^>]*>/g)].map((match) => match[1]!);
      return hrefs.length > 0 && hrefs.every((href) => ids.has(href));
    });
  expect(
    navs,
    "PRIVNAV-01: one native jump navigation resolving into policy sections",
  ).toHaveLength(1);
  return navs[0]!;
}
function jumpLinks(html: string) {
  return [...jumpNav(html).matchAll(/<a\b[^>]*>[\s\S]*?<\/a>/g)].map(([value]) => value);
}
function sectionPermalink(html: string, id: string) {
  const links = [...withoutNavs(policyInner(html)).matchAll(/<a\b[^>]*>[\s\S]*?<\/a>/g)].map(
    ([value]) => value,
  );
  return links.filter((link) => attribute(link, "href") === `#${id}`);
}

let fixture: Awaited<ReturnType<typeof createPrivacySectionFixture>>;
beforeAll(async () => {
  fixture = await createPrivacySectionFixture();
});
afterAll(() => {
  fixture?.close();
});

for (const renderer of ["Hono", "Kit"] as const) {
  describe(`${renderer} privacy section navigation`, () => {
    it("PRIVNAV-01 indexes all six sections with native, descriptive jump links", async () => {
      const { html } = await fixture.render(renderer);
      expect(POLICY_SECTION_TITLES).toHaveLength(6);
      const headings = sectionHeadings(html);
      expect(headings).toHaveLength(6);
      const nav = jumpNav(html);
      expect(accessibleName(nav, html).length).toBeGreaterThan(0);
      expect(nav).not.toMatch(/\bstyle="/);
      // The compact jump style is the existing shared `.jump` list (same as
      // the house-rules jump index), not a one-off layout.
      expect(nav).toMatch(/<ul\b[^>]*class="[^"]*\bjump\b[^"]*"[^>]*>/);
      const links = jumpLinks(html);
      expect(links).toHaveLength(6);
      const ids = sectionIds(html);
      expect(links.map((link) => attribute(link, "href"))).toEqual(ids.map((id) => `#${id}`));
      links.forEach((link, index) => {
        expect(accessibleName(link, html)).toContain(POLICY_SECTION_TITLES[index]!);
        expect(attribute(link, "onclick")).toBe("");
        expect(attribute(link, "tabindex")).not.toBe("-1");
        expect(attribute(link, "aria-hidden")).not.toBe("true");
      });
      expect(
        links.map((link) => accessibleName(link, html)),
        "the history chrome is not a policy section",
      ).not.toContainEqual(expect.stringContaining("Previous published"));
    });

    it("PRIVNAV-02 gives every section a unique deterministic permalink from the shared source", async () => {
      const { html } = await fixture.render(renderer);
      const headings = sectionHeadings(html);
      expect(headings).toHaveLength(6);
      const ids = sectionIds(html);
      expect(new Set(ids).size).toBe(6);
      const allIds = [...html.matchAll(/\bid="([^"]+)"/g)].map((match) => match[1]!);
      headings.forEach((heading, index) => {
        const id = ids[index]!;
        expect(id).toMatch(/^[A-Za-z][A-Za-z0-9_-]*$/);
        expect(allIds.filter((candidate) => candidate === id)).toHaveLength(1);
        const title = POLICY_SECTION_TITLES[index]!;
        // Anchor chrome (a permalink inside the heading) is not policy copy.
        const headingCopy = text(heading.inner.replace(/<a\b[^>]*>[\s\S]*?<\/a>/g, ""));
        expect(headingCopy).toBe(title);
        const permalinks = sectionPermalink(html, id);
        expect(permalinks, "PRIVNAV-02: each section has its own resolving permalink").toHaveLength(
          1,
        );
        expect(accessibleName(permalinks[0]!, html)).toContain(title);
        expect(attribute(permalinks[0]!, "tabindex")).not.toBe("-1");
        expect(attribute(permalinks[0]!, "aria-hidden")).not.toBe("true");
      });
      // Deterministic: a second render keeps every address.
      expect(sectionIds((await fixture.render(renderer)).html)).toEqual(ids);
    });

    it("PRIVNAV-05 preserves exact policy copy/order, strap, history and actions", async () => {
      const { html } = await fixture.render(renderer);
      expect(html).toMatch(/<h1\b[^>]*id="privacy-heading"[^>]*>Privacy policy<\/h1>/);
      const headings = sectionHeadings(html);
      expect(headings).toHaveLength(6);
      headings.forEach((heading, index) => {
        const headingCopy = text(heading.inner.replace(/<a\b[^>]*>[\s\S]*?<\/a>/g, ""));
        expect(headingCopy).toBe(POLICY_SECTION_TITLES[index]!);
      });
      expect(html).toContain("Version 6");
      expect(html).toContain("current policy");
      expect(html).toMatch(/<h2\b[^>]*>\s*Previous published versions\s*<\/h2>/);
      for (const entry of PREVIOUS_PUBLISHED_POLICIES) expect(html).toContain(entry.href);
      expect(html).toMatch(
        /<a\b[^>]*href="\/join"[^>]*data-testid="privacy-join"[^>]*>Join with Discord<\/a>/,
      );
      expect(html).toContain('href="/">Back to the homepage</a>');
    });

    it("PRIVNAV-06 remains a public, script-free page when session/DB bindings are unavailable", async () => {
      // The fixture's env Proxy throws on any binding beyond APP_URL.
      const { html, status, headers } = await fixture.render(renderer);
      expect(status).toBe(200);
      expect(headers["cache-control"]).toBe("public, max-age=3600");
      expect(headers["set-cookie"]).toBeUndefined();
      expect(html).toContain(`rel="canonical" href="${PRIVACY_NAV_ORIGIN}/privacy"`);
      expect(html).not.toMatch(/<script\b/i);
      // One inlined leaf bundle, no one-off style block for the navigation.
      expect(html.match(/<style\b/g) ?? []).toHaveLength(1);
      if (renderer === "Kit") {
        expect(fixture.csr).toBe(false);
        expect(
          fixture.modules.filter((module) => /(?:^|\/)(?:db|sessions?)(?:[/.]|$)/i.test(module)),
        ).toEqual([]);
      }
    });
  });
}

describe("privacy section renderer fixtures", () => {
  it("PRIVNAV-03a keeps duplicate headings addressable with unique deterministic ids", () => {
    const first = renderPolicyMarkdown(
      "## Duplicate section\n\nFirst body.\n\n## Duplicate section\n\nSecond body.\n\n## Deletion\n\nOne.\n\n## Deletion\n\nTwo.\n",
    );
    const ids = [...first.matchAll(/<h2\b[^>]*id="([^"]+)"[^>]*>/g)].map((match) => match[1]!);
    expect(ids).toHaveLength(4);
    for (const id of ids) expect(id).toMatch(/^[A-Za-z][A-Za-z0-9_-]*$/);
    expect(new Set(ids).size).toBe(4);
    expect(
      renderPolicyMarkdown(
        "## Duplicate section\n\nFirst body.\n\n## Duplicate section\n\nSecond body.\n\n## Deletion\n\nOne.\n\n## Deletion\n\nTwo.\n",
      ),
    ).toBe(first);
  });

  it("PRIVNAV-03b keeps hostile headings inert: escaped content, valid ids, no new elements", () => {
    const html = renderPolicyMarkdown(
      '## <img src=x onerror=alert(1)>\n\n<script>alert("x")</script>\n\n[evil](https://evil.test)\n\n**unclosed\n',
    );
    expect(html).not.toContain("<script>");
    expect(html).toContain("&lt;script&gt;");
    expect(html).not.toContain("<img");
    expect(html).toContain("&lt;img");
    expect(html).not.toContain("<a ");
    const ids = [...html.matchAll(/<h2\b[^>]*id="([^"]+)"[^>]*>/g)].map((match) => match[1]!);
    expect(ids).toHaveLength(1);
    expect(ids[0]).toMatch(/^[A-Za-z][A-Za-z0-9_-]*$/);
    expect(
      renderPolicyMarkdown(
        '## <img src=x onerror=alert(1)>\n\n<script>alert("x")</script>\n\n[evil](https://evil.test)\n\n**unclosed\n',
      ),
    ).toBe(html);
  });

  it("PRIVNAV-03c maps URL-hostile headings to fragment-safe ids without touching their text", () => {
    const html = renderPolicyMarkdown(
      '## A & B "quoted"\n\n## 100% sure? yes#1\n\n## Ünïcodé 🎉 party\n\n## a/b\\c:d;e,f.g!h\'i(j)k\n',
    );
    const headings = [...html.matchAll(/<h2\b[^>]*>([\s\S]*?)<\/h2>/g)];
    expect(headings).toHaveLength(4);
    const ids = headings.map((match) =>
      attribute(match[0].slice(0, match[0].indexOf(">") + 1), "id"),
    );
    for (const id of ids) expect(id).toMatch(/^[A-Za-z][A-Za-z0-9_-]*$/);
    expect(new Set(ids).size).toBe(4);
    expect(text(headings[0]![1]!)).toContain("A & B");
    expect(text(headings[1]![1]!)).toBe("100% sure? yes#1");
    expect(text(headings[2]![1]!)).toContain("party");
    expect(
      renderPolicyMarkdown(
        '## A & B "quoted"\n\n## 100% sure? yes#1\n\n## Ünïcodé 🎉 party\n\n## a/b\\c:d;e,f.g!h\'i(j)k\n',
      ),
    ).toBe(html);
  });
});

it("PRIVNAV-02b derives both renderers from one section authority, not copied inventories", () => {
  // The jump labels must equal the live policy headings in order (proved per
  // renderer in PRIVNAV-01/02); here the source side: neither renderer file
  // may carry its own copy of the heading inventory.
  expect(policySectionTitles(readFileSync(resolve(root, POLICY_FILE), "utf8"))).toEqual(
    POLICY_SECTION_TITLES,
  );
  expect(POLICY_SECTION_TITLES).toHaveLength(6);
  const needles = [
    "Who we are, and what this covers",
    "Cookies and tracking",
    "Changes to this policy",
  ];
  const rendererFiles = [join(root, "src/screens/privacy.tsx")];
  for (const entry of readdirSync(join(root, "web/src/routes/privacy"), { withFileTypes: true })) {
    if (entry.isFile() && /\.(svelte|ts)$/.test(entry.name))
      rendererFiles.push(join(root, "web/src/routes/privacy", entry.name));
  }
  for (const file of rendererFiles) {
    const body = readFileSync(file, "utf8");
    for (const needle of needles)
      expect(body, `copied heading inventory in ${file}`).not.toContain(needle);
  }
});

it("PRIVNAV-04 preserves the same shareable addresses across both renderers", async () => {
  const hono = (await fixture.render("Hono")).html;
  const kit = (await fixture.render("Kit")).html;
  expect(sectionIds(hono)).toHaveLength(6);
  expect(sectionIds(kit)).toEqual(sectionIds(hono));
  expect(jumpLinks(kit).map((link) => attribute(link, "href"))).toEqual(
    jumpLinks(hono).map((link) => attribute(link, "href")),
  );
  expect(jumpLinks(kit).map((link) => accessibleName(link, kit))).toEqual(
    jumpLinks(hono).map((link) => accessibleName(link, hono)),
  );
});

it("PRIVNAV-07 keeps the Markdown alternate byte-identical to the published policy source", async () => {
  expect(POLICY_VERSION).toBe(6);
  expect(POLICY_FILE).toBe("content/privacy-policy-v6.md");
  const res = await app.request("/privacy.md", {}, env);
  expect(res.status).toBe(200);
  expect(res.headers.get("content-type")).toContain("text/markdown");
  const body = await res.text();
  expect(body).toBe(mdPrivacy(env.APP_URL!));
  expect(body).toContain(`Version ${POLICY_VERSION}`);
  expect(body).toContain(POLICY_MARKDOWN.trimEnd());
  for (const entry of PREVIOUS_PUBLISHED_POLICIES) expect(body).toContain(entry.href);
});
